def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    from collections import Counter
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    pts=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (bg,2)]
    # ARC rule: the singleton color marks ray color; marker becomes 4.
    if not pts: return g
    color=pts[0][2]
    # Two horizontal 2-markers at opposite top/bottom edges send rays downward.
    if g[0].count(2)>=2:
        for c,v in enumerate(g[0]):
            if v==2:
                for r in range(1,h):
                    if g[r][c]==bg: g[r][c]=color
        for r,c,v in pts:
            g[r][c]=4
            for rr in range(r+1,h):
                if g[rr][c]==bg: g[rr][c]=color
        return g
    # Vertical edge markers define horizontal rays; special pixels set the ray color.
    for r,c,v in pts:
        g[r][c]=4
        for cc in range(c+1,w):
            if g[r][cc]==bg: g[r][cc]=color
    # Corner marker on the opposite edge starts the companion ray.
    if g[0][0] not in (bg,2) and g[0][0]!=color:
        for cc in range(1,w):
            if g[0][cc]==bg: g[0][cc]=color
    # vertical 2-bars on opposite sides create a corresponding row ray
    bars=[]
    for c in range(w):
        rows=[r for r in range(h) if g[r][c]==2]
        if len(rows)>=2: bars.append((c,min(rows)))
    if len(bars)>=2:
        for c,first in bars:
            if c==0 or c==w-1:
                for cc in range(1,w):
                    if g[first][cc]==bg: g[first][cc]=color
    return g

